package com.technova.security;
import com.technova.repo.UsuarioRepository; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(UsuarioRepository repo, PasswordEncoder encoder){return username->{var u=repo.findByUsernameAndEstadoTrue(username).orElseThrow(()->new UsernameNotFoundException("Usuario no encontrado")); if(u.getPassword()==null || !u.getPassword().startsWith("$2")){u.setPassword(encoder.encode(u.getPassword()));repo.save(u);} return User.withUsername(u.getUsername()).password(u.getPassword()).roles(u.getRol()).build();};}
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.authorizeHttpRequests(a->a.requestMatchers("/","/inicio","/catalogo","/carrito/**","/checkout","/contacto","/ubicacion","/css/**","/js/**","/api/public/**","/error").permitAll().requestMatchers("/admin/**","/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/admin/dashboard",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout").permitAll()).csrf(c->c.ignoringRequestMatchers("/api/**")).build();}
}
